    "path": "tgcloud/lib/pet/data/missfrozen_pet_migration.json",
    "content": "{\n  \"format\": \"missfrozen_pet_migration_v1\",\n  \"source\": \"economy.db\",\n  \"generated_at_utc\": \"2026-10-22T10:04:40+00:00\",\n  \"record_count\": 4,\n  \"users_with_pets\": 4,\n  \"pet_record_count\": 6,\n  \"users\": [\n    {\n      \"user_id\": 1292564068,\n      \"owned_pets\": [\n        {\n          \"pet_id\": \"axofly\",\n          \"level\": 1,\n          \"xp\": 875,\n          \"equipped\": true,\n          \"custom_name\": \"...❄️Snowwy༻꧂\"\n        }\n      ]\n    },\n    {\n      \"user_id\": 5067983759,\n      \"owned_pets\": [\n        {\n          \"pet_id\": \"axofly\",\n          \"level\": 1,\n          \"xp\": 825,\n          \"equipped\": true,\n          \"custom_name\": null\n        }\n      ]\n    },\n    {\n      \"user_id\": 6100847287,\n      \"owned_pets\": [\n        {\n          \"pet_id\": \"axofly\",\n          \"level\": 1,\n          \"xp\": 0,\n          \"equipped\": true,\n          \"custom_name\": null\n        },\n        {\n          \"pet_id\": \"capycorn\",\n          \"level\": 1,\n          \"xp\": 0,\n          \"equipped\": false,\n          \"custom_name\": null\n        }\n      ]\n    },\n    {\n      \"user_id\": 6972384968,\n      \"owned_pets\": [\n        {\n          \"pet_id\": \"axofly\",\n          \"level\": 1,\n          \"xp\": 0,\n          \"equipped\": true,\n          \"custom_name\": null\n        },\n        {\n          \"pet_id\": \"capycorn\",\n          \"level\": 1,\n          \"xp\": 150,\n          \"equipped\": false,\n          \"custom_name\": null\n        }\n      ]\n    }\n  ]\n}\n"
